const $=selector=>document.querySelector(selector);
const state={lang:localStorage.getItem('frontier-language')==='en'?'en':'zh',apiBase:'',apiReady:false,session:sessionStorage.getItem('frontier-session')||'',email:sessionStorage.getItem('frontier-email')||'',isAdmin:false,adminData:null};
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
async function api(path,options={}) {const response=await fetch(state.apiBase+path,{...options,headers:{'Content-Type':'application/json',...(state.session?{'Authorization':`Bearer ${state.session}`}:{}) ,...(options.headers||{})}});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`HTTP ${response.status}`);return data;}
function adminDate(value){return value?new Date(value).toLocaleString(state.lang==='zh'?'zh-CN':'en-US',{year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'—';}
function renderAdminData(){
  if(!state.adminData)return;
  const zh=state.lang==='zh',users=state.adminData.users||[],invitations=state.adminData.invitations||[];
  const active=users.filter(item=>!item.revokedAt).length,pending=invitations.filter(item=>!item.acceptedAt&&!item.revokedAt&&Date.parse(item.expiresAt)>Date.now()).length;
  $('#admin-summary').innerHTML=`<span>${users.length} ${zh?'个账号':'accounts'}</span><span>${active} ${zh?'个可访问':'active'}</span><span>${pending} ${zh?'个待接受邀请':'pending invitations'}</span>`;
  $('#admin-users').innerHTML=users.length?users.map(item=>`<div class="admin-row"><div><b>${esc(item.email)}</b><small><span class="state ${item.revokedAt?'revoked':''}">${item.revokedAt?(zh?'已撤销':'Revoked'):(zh?'可访问':'Active')}</span> · ${zh?'注册':'Joined'} ${esc(adminDate(item.createdAt))} · ${zh?'最近登录':'Last sign-in'} ${esc(adminDate(item.lastSignedInAt))}<br>${zh?'行程':'Trips'} ${Number(item.reminderCount)||0} · ${zh?'有效提醒':'Active reminders'} ${Number(item.activeReminderCount)||0}</small></div>${item.email.toLowerCase()===state.email.toLowerCase()?'':`<button type="button" class="${item.revokedAt?'':'danger'}" data-user-id="${esc(item.id)}" data-action="${item.revokedAt?'restore':'revoke'}">${item.revokedAt?(zh?'恢复访问':'Restore access'):(zh?'撤销访问':'Revoke access')}</button>`}</div>`).join(''):`<p class="muted">${zh?'暂无账号':'No accounts yet'}</p>`;
  $('#admin-invitations').innerHTML=invitations.length?invitations.map(item=>{const pending=!item.acceptedAt&&!item.revokedAt&&Date.parse(item.expiresAt)>Date.now();const status=item.acceptedAt?(zh?'已接受':'Accepted'):item.revokedAt?(zh?'已撤销':'Revoked'):pending?(zh?'待接受':'Pending'):(zh?'已过期':'Expired');return `<div class="admin-row"><div><b>${esc(item.email)}</b><small>${status} · ${zh?'发送':'Sent'} ${esc(adminDate(item.createdAt))} · ${zh?'到期':'Expires'} ${esc(adminDate(item.expiresAt))}</small></div>${pending?`<button type="button" class="danger" data-invite-id="${esc(item.id)}" data-action="revoke-invite">${zh?'取消邀请':'Cancel invitation'}</button>`:''}</div>`;}).join(''):`<p class="muted">${zh?'暂无邀请':'No invitations yet'}</p>`;
}
async function loadAdmin(){if(!state.isAdmin)return;state.adminData=await api('/admin/overview');renderAdminData();}

function renderStatus(){
 const zh=state.lang==='zh';$('#admin-content').hidden=!state.isAdmin;
 $('#admin-gate').hidden=state.isAdmin;$('#admin-gate').textContent=!state.apiReady?(zh?'管理功能尚未启用：需连接邮件与账号服务。':'Admin is not active yet: email and account services must be connected.'):!state.session?(zh?'请使用管理员邮箱验证登录。':'Verify your admin email to sign in.'):(zh?'此账号没有管理员权限。':'This account does not have admin access.');
 $('#admin-login').hidden=!state.apiReady||!!state.session;$('#admin-session').hidden=!state.session;$('#user-email').textContent=state.email;
}
function setLanguage(lang){state.lang=lang;localStorage.setItem('frontier-language',lang);document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.querySelectorAll('[data-zh]').forEach(el=>el.textContent=el.dataset[lang]);$('#lang').textContent=lang==='zh'?'English':'中文';renderStatus();renderAdminData();}
function clearSession(){state.session='';state.email='';state.isAdmin=false;state.adminData=null;sessionStorage.removeItem('frontier-session');sessionStorage.removeItem('frontier-email');$('#admin-users').replaceChildren();$('#admin-invitations').replaceChildren();renderStatus();}
async function init(){
 try{const response=await fetch('config.json');const config=await response.json();state.apiBase=(config.apiBase||'').replace(/\/$/,'');if(state.apiBase){await api('/health');state.apiReady=true;}if(state.apiReady&&state.session){const me=await api('/me');state.email=me.email;state.isAdmin=me.isAdmin===true;await loadAdmin();}}
 catch(error){if(error.message.includes('401')||error.message.includes('403'))clearSession();else $('#login-message').textContent=error.message;}
 setLanguage(state.lang);
}
$('#lang').addEventListener('click',()=>setLanguage(state.lang==='zh'?'en':'zh'));
$('#sign-out').addEventListener('click',clearSession);
$('#admin-login').addEventListener('submit',async event=>{event.preventDefault();try{await api('/auth/start',{method:'POST',body:JSON.stringify({email:$('#login-email').value.trim()})});$('#login-message').textContent=state.lang==='zh'?'如有访问权限，登录链接将发至邮箱。验证后点击网站「管理」返回此页。':'If access is allowed, check your email for the sign-in link. After verification, choose Admin on the website to return here.';}catch(error){$('#login-message').textContent=error.message;}});
$('#admin-invite-form').addEventListener('submit',async event=>{event.preventDefault();const email=$('#admin-invite-email').value.trim();try{await api('/admin/invitations',{method:'POST',body:JSON.stringify({email})});$('#admin-invite-email').value='';$('#admin-message').textContent=state.lang==='zh'?`邀请已发送给 ${email}`:`Invitation sent to ${email}`;await loadAdmin();}catch(error){$('#admin-message').textContent=error.message;}});
$('#admin-users').addEventListener('click',async event=>{const button=event.target.closest('button[data-user-id]');if(!button)return;const action=button.dataset.action;if(action==='revoke'&&!confirm(state.lang==='zh'?'撤销此账号访问并停止未来提醒？':'Revoke this account and stop future reminders?'))return;try{await api(`/admin/users/${encodeURIComponent(button.dataset.userId)}/${action}`,{method:'POST'});$('#admin-message').textContent=action==='revoke'?(state.lang==='zh'?'访问已撤销。':'Access revoked.'):(state.lang==='zh'?'访问已恢复；用户需要重新登录。':'Access restored; the user must sign in again.');await loadAdmin();}catch(error){$('#admin-message').textContent=error.message;}});
$('#admin-invitations').addEventListener('click',async event=>{const button=event.target.closest('button[data-invite-id]');if(!button)return;try{await api(`/admin/invitations/${encodeURIComponent(button.dataset.inviteId)}/revoke`,{method:'POST'});$('#admin-message').textContent=state.lang==='zh'?'邀请已取消。':'Invitation canceled.';await loadAdmin();}catch(error){$('#admin-message').textContent=error.message;}});

init();
